/* test_shim_ref.c - ground truth for the JS shim's double formatting
 * and strtod, generated by the REAL C library on this machine.
 * Build: clang test_shim_ref.c -o /tmp/shim_ref && /tmp/shim_ref
 * Output lines: spec|value-hex|rendered   and  STR|text|value-hex
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static double vals[] = {
    0.0, -0.0, 1.0, -1.0, 0.5, 1.5, 2.25, -2.75, 0.1, 0.2, 0.3,
    1.0 / 3.0, 3.141592653589793, 2.718281828459045, 1e10, 1e-10,
    1e100, 1e-100, 1e308, 1e-308, 5e-324, 123456789.123456789,
    1.7976931348623157e308, 2.2250738585072014e-308, 54.0, 65536.0,
    2.5, 3.5, 1.25, 0.125, 7.5, 0.0625,
};
static const char *strs[] = {
    "0.0", "-0.0", "1.5", "-2.75", "0.1", "1e10", "1E-10", "3.141592653589793",
    "  +42.5", ".5", "5.", "0x10", "1e", "1e+", "abc", "", "1.5e3", "-.25",
    "inf", "-inf", "+inf", "nan", "-nan", "0x1p-3", "-0x1p-3", "0x1.8p1",
    "0x1p+4", "0X1P-2",
};

int main(void) {
    int n = (int)(sizeof(vals) / sizeof(vals[0]));
    for (int i = 0; i < n; i++) {
        double v = vals[i];
        unsigned char *b = (unsigned char *)&v;
        char hex[17];
        for (int k = 0; k < 8; k++) sprintf(hex + 2 * k, "%02x", b[7 - k]);
        printf("g17|%s|%.17g\n", hex, v);
        printf("g6|%s|%g\n", hex, v);
        printf("f6|%s|%.6f\n", hex, v);
        printf("e6|%s|%.6e\n", hex, v);
        printf("e17|%s|%.17e\n", hex, v);
        printf("e0|%s|%.0e\n", hex, v);
        printf("g5|%s|%.5g\n", hex, v);
    }
    int m = (int)(sizeof(strs) / sizeof(strs[0]));
    for (int i = 0; i < m; i++) {
        char *end = 0;
        double v = strtod(strs[i], &end);
        unsigned char *b = (unsigned char *)&v;
        char hex[17];
        for (int k = 0; k < 8; k++) sprintf(hex + 2 * k, "%02x", b[7 - k]);
        printf("STR|%s|%s|%ld\n", strs[i], hex, (long)(end - strs[i]));
    }
    return 0;
}
